BEGIN TRANSACTION;;
CREATE TABLE "budget" (
"budget_id" TEXT,
  "department" TEXT,
  "fiscal_year" INTEGER,
  "allocated_amount" REAL,
  "currency" TEXT
);;
CREATE TABLE "completion" (
"completion_id" TEXT,
  "enrollment_id" TEXT,
  "completion_date" TEXT,
  "result" TEXT
);;
CREATE TABLE "course" (
"course_id" TEXT,
  "course_name" TEXT,
  "duration_hours" INTEGER,
  "cost" REAL,
  "capacity" INTEGER,
  "available_from" TEXT,
  "available_to" TEXT,
  "status" TEXT
);;
CREATE TABLE "course_skill" (
"course_id" TEXT,
  "skill_id" TEXT,
  "expected_proficiency_gain" INTEGER
);;
CREATE TABLE "employee" (
"employee_id" TEXT,
  "role_id" TEXT,
  "department" TEXT,
  "joining_date" TEXT,
  "status" TEXT
);;
CREATE TABLE "employee_skill" (
"employee_id" TEXT,
  "skill_id" TEXT,
  "proficiency" INTEGER,
  "assessed_on" TEXT,
  "assessment_status" TEXT,
  "gap" INTEGER
);;
CREATE TABLE "enrollment" (
"enrollment_id" TEXT,
  "employee_id" TEXT,
  "course_id" TEXT,
  "enrollment_date" TEXT,
  "status" TEXT
);;
CREATE TABLE "prerequisite" (
"course_id" TEXT,
  "prerequisite_course_id" TEXT,
  "required" INTEGER
);;
CREATE TABLE "role" (
"role_id" TEXT,
  "role_name" TEXT,
  "department" TEXT,
  "status" TEXT
);;
CREATE TABLE "role_skill_target" (
"role_id" TEXT,
  "skill_id" TEXT,
  "target_proficiency" INTEGER,
  "effective_from" TEXT,
  "effective_to" TEXT
);;
CREATE TABLE "skill" (
"skill_id" TEXT,
  "skill_name" TEXT,
  "category" TEXT,
  "status" TEXT
);;
COMMIT;;
